    guilt: () => `<path d="M24 6v36M14 16h20" stroke="${K}" stroke-width="8"/><path d="M24 6v36M14 16h20" stroke="#8a1a2a" stroke-width="4"/><path d="M8 34q6-4 12 0t12 0 12 0" stroke="#aab" stroke-width="2.4" fill="none" stroke-dasharray="3 2"/>`,
