    guard: () => `<path d="M24 4l16 6v12c0 10-7 18-16 22C15 40 8 32 8 22V10z" fill="#6a8ad0" ${st}/>${shine(17, 14, 3)}`,
    evasive: () => `<path d="M8 14h22q8 0 8 6t-8 6M4 24h18M10 34h20q6 0 6 5" fill="none" stroke="#3fb8a9" stroke-width="3.4" stroke-linecap="round"/>`,
    empower: () => `<path d="M14 22q0-8 6-8h10q6 0 6 8v8q0 10-10 12h-4q-8-2-8-10z" fill="#e8742a" ${st}/><path d="M20 14v8M26 14v8M32 16v6" ${st}/><path d="M24 2l5 6h-10z" fill="#f2c14e" ${st} stroke-width="1.2"/>`,
