    secondwind: () => `<path d="M6 18h24q8 0 8-6t-7-5M4 28h30q8 0 8 6t-7 5M10 38h14" fill="none" stroke="#f2c14e" stroke-width="4" stroke-linecap="round"/><path d="M6 18h24q8 0 8-6t-7-5M4 28h30q8 0 8 6t-7 5" fill="none" stroke="${K}" stroke-width="1.2"/>`,
